class Solution {
public:
    int maxDigitRange(vector<int>& nums) {
        int bestRange = -1, sum = 0;
        for (int value : nums) {
            int x = value, lo = 9, hi = 0;
            while (x) { lo = min(lo, x % 10); hi = max(hi, x % 10); x /= 10; }
            int range = hi - lo;
            if (range > bestRange) { bestRange = range; sum = value; }
            else if (range == bestRange) sum += value;
        }
        return sum;
    }
};
